    window.parent.postMessage({
      type: "gadgets.frontend-error.v1",
      report: {
        failureSite,
        severity: options.severity ?? "error",
        handled: options.handled ?? true,
        captureMechanism: options.captureMechanism || "explicit",
        exception: serializeException(caught),
