    for (const [key, value] of Object.entries(groups)) {
      if (typeof value === "string" && value.length > 0 && !/^[0-9]+$/.test(key)) {
        out[key] = decodeURIComponent(value);
      }
    }
    return out;
  } catch (error) {
    return null;
  }
}

