    .replace(/^import\s+type\s+[^;]+;\s*\n?/gm, blankCode)
    .replace(/^export\s+{};\s*\n?/gm, blankCode)
    .replace(/^\/\/# sourceMappingURL=.*$/gm, blankCode)
    .replace(/export[\t ]+default[\t ]+/, match => "return".padEnd(match.length));
}

